package com.careerguidance.controller; import com.careerguidance.dto.response.AssignedStudentResponse; import com.careerguidance.service.MentorReviewService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mentor/students") public class StudentReviewController {private final MentorReviewService service;public StudentReviewController(MentorReviewService s){service=s;} @GetMapping @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public Page<AssignedStudentResponse> list(Authentication a,@PageableDefault(size=20,sort="id") Pageable p){return service.students(a,p);} @GetMapping("/{id}") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public AssignedStudentResponse get(Authentication a,@PathVariable Long id){return service.student(a,id);}}
